select p.desc_produto, p.grade, p.griffe, p.linha, p.grupo_produto, p.subgrupo_produto, p.inativo, 
		p.fabricante,pb.CODIGO_BARRA, pb.PRODUTO, pb.COR_PRODUTO, pb.TAMANHO, pb.grade as grade_sku, 
		pp.preco1 as preco_custo, ppv.preco1 as preco_venda_loja
from produtos_barra pb 
inner join produtos p on p.produto = pb.produto
inner join produtos_precos pp on pp.CODIGO_TAB_PRECO='00' and pp.produto = pb.PRODUTO
inner join produtos_precos ppv on ppv.CODIGO_TAB_PRECO='60' and ppv.produto = pb.PRODUTO
